#include <iostream>
#include <vector>

using namespace std;

int main() {
    int N;
    cin >> N;

    vector<int> A(N);
    for(int i = 0; i < N; ++i) // A をすべて入力する
        cin >> A[i];

    for(int i = 0; i < N; ++i)
        for(int j = 0; j < N; ++j)
            if(A[i] != A[j]){ // 違うペアがあったら
                cout << "No" << endl; // No と出力して
                return 0; // 終了
            }

    // 違うペアがなかったら
    cout << "Yes" << endl; // Yes と出力して
    return 0; // 終了
}

#include <iostream>
#include <vector>

using namespace std;

int main() {
    int N;
    cin >> N;

    vector<int> A(N);
    for(auto&& a : A) // A をすべて入力する
        cin >> a;

    for(auto a : A)
        for(auto b : A)
            if(a != b){ // 違うペアがあったら
                cout << "No" << endl; // No と出力して
                return 0; // 終了
            }

    // 違うペアがなかったら
    cout << "Yes" << endl; // Yes と出力して
    return 0; // 終了
}

#include <iostream>

using namespace std;

int main() {
    int N, A1; // A の先頭を先に読んでおく
    cin >> N >> A1;

    for (int i = 1; i < N; ++i) { // A の残りについて
        int A;
        cin >> A; // 読み込んで
        if (A != A1) { // 等しくなければ No を出力して終了
            cout << "No" << endl;
            return 0;
        }
    }
    // すべて判定が終わってここに到達したら Yes
    cout << "Yes" << endl;
    return 0;
}
